import type { System } from "../../Engine/System";
import type { World } from "../../Engine/World";
import type { Plane } from "../Entity/Plane";
import { BATTLE_EVENT } from "../BattleEvents";
import type { WeaponConfig } from "../Config/WeaponConfig";
import { Bullet } from "../Entity/Bullet";

export interface BulletSpawnParams {
    x: number; y: number;
    dirX: number; dirY: number;
    speed: number; damage: number;
    isPlayerBullet: boolean;
}


export class BulletSpawnSystem implements System {

  
    private _world: World = null!;

    onStart(world: World): void {
        this._world = world;
        world.bus.on(BATTLE_EVENT.WEAPON_FIRE, this._onWeaponFire, this);
        world.bus.on(BATTLE_EVENT.BULLET_SPAWN_REQUEST, this._onSpawnRequest, this);
    }

    onDestroy(world: World): void {
        world.bus.off(BATTLE_EVENT.WEAPON_FIRE, this._onWeaponFire, this);
         world.bus.off(BATTLE_EVENT.BULLET_SPAWN_REQUEST, this._onSpawnRequest, this);  
        this._world = null!;
    }

    // 事件驱动的，不需要每帧遍历
    onTick(world: World, dt: number): void {
        // 留空
    }

    private _onWeaponFire(p: Plane, w: WeaponConfig): void {
        this.spawn({
            x: p.x + w.fireDirX * 20,
            y: p.y + w.fireDirY * 20,
            dirX: w.fireDirX,
            dirY: w.fireDirY,
            speed: w.bulletSpeed,
            damage: w.bulletDamage,
            isPlayerBullet: p.kind === 'player',
        });
    }

     private _onSpawnRequest(params: BulletSpawnParams): void {
        this.spawn(params);
    }

    // 唯一创建出口
    private spawn(params: BulletSpawnParams): void {
        const b = new Bullet();
        b.x = params.x;
        b.y = params.y;
        b.dirX = params.dirX;
        b.dirY = params.dirY;
        b.speed = params.speed;
        b.damage = params.damage;
        b.isPlayerBullet = params.isPlayerBullet;
        this._world.add(b);
    }

}